R=Path(__file__).resolve().parents[1];pdfmetrics.registerFont(TTFont('Noto',R/'app/fonts/noto-sans-kr-regular.ttf'));pdfmetrics.registerFont(TTFont('NotoB',R/'app/fonts/noto-sans-kr-bold.ttf'));G=HexColor('#245c44');I=HexColor('#1d2520');M=HexColor('#68736c');P=HexColor('#f2efe7');L=HexColor('#d9d5ca')
S={'t':ParagraphStyle('t',fontName='NotoB',fontSize=30,leading=38,textColor=I),'h':ParagraphStyle('h',fontName='NotoB',fontSize=19,leading=26,textColor=G,spaceBefore=6,spaceAfter=10),'b':ParagraphStyle('b',fontName='Noto',fontSize=9.3,leading=15,textColor=I,spaceAfter=8),'s':ParagraphStyle('s',fontName='Noto',fontSize=7.5,leading=11,textColor=M),'c':ParagraphStyle('c',fontName='NotoB',fontSize=11,leading=17,textColor=G,alignment=TA_CENTER)}
